WITH segment_daily AS ( SELECT cd.cd_gender, cd.cd_education_status, d.d_date, d.d_year, d.d_month_seq, SUM(ss.ss_net_paid) AS daily_net_paid, COUNT(*) AS daily_txn_cnt, CASE WHEN cd.cd_purchase_estimate < 1000 THEN 'Low' WHEN cd.cd_purchase_estimate BETWEEN 1000 AND 5000 THEN 'Medium' ELSE 'High' END AS purchase_estimate_bucket, COUNT(DISTINCT s.s_state) AS distinct_state_cnt FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk GROUP BY cd.cd_gender, cd.cd_education_status, d.d_date, d.d_year, d.d_month_seq, cd.cd_purchase_estimate ) SELECT cd_gender, cd_education_status, d_year, d_month_seq, daily_txn_cnt, daily_net_paid, distinct_state_cnt, SUM(daily_net_paid) OVER (PARTITION BY cd_gender, cd_education_status ORDER BY d_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total_net_paid, purchase_estimate_bucket FROM segment_daily WHERE daily_txn_cnt >= 5 ORDER BY cd_gender, cd_education_status, d_date
